refentry.refsect1:
&reftitle.changelog;





    &Version;
    &Description;





    8.4.0

     SOAP_PERSISTENCE_SESSION fonctionne désormais
     lorsque l'extension session est compilée en module partagé ;
     auparavant, l'échec était silencieux.
     SoapServer::setPersistence lève désormais
     aussi une Error lorsque
     SOAP_PERSISTENCE_SESSION est demandé alors que
     l'extension session n'est pas disponible.

  &reftitle.examples;



    Exemple SoapServer::setPersistence


<?php

class MyFirstPersistentSoapServer
{
    private $resource; // (Par exemple PDO, mysqli, etc..)
    public $myvar1;
    public $myvar2;

    public function __construct()
    {
        $this->resource = CodeToStartOurResourceUp(); // On démarre notre ressource
    }

    public function __unserialize(array $data): void
    {
        $this->myvar1 = $data['myvar1'];
        $this->myvar2 = $data['myvar2'];

        $this->resource = CodeToStartOurResourceUp();
    }

    public function __serialize(): array
    {
        // On s'assure d'enlever $resource ici, ainsi nos données peuvent persister en session.
        // Si on oublie, la désérialisation lors de la prochaine requête échouera et un objet
        // MyFirstPersistentSoapServer ne sera donc pas persistant entre les requêtes.
        return [
            'myvar1' => $this->myvar1,
            'myvar2' => $this->myvar2,
        ];
    }
}

try {
    session_start();
    $server = new SoapServer(null, ['uri' => $_SERVER['REQUEST_URI']]);
    $server->setClass('MyFirstPersistentSoapServer');
    // setPersistence() DOIT être appelée après setClass(), car le comportement de setClass()
    // affecte SOAP_PERSISTENCE_REQUEST.
    $server->setPersistence(SOAP_PERSISTENCE_SESSION);
    $server->handle();
} catch (SoapFault $e) {
    error_log("SOAP ERROR: " . $e->getMessage());
}
